import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"53、【渐】 艮下巽上","description":"周易阐真 - 53、【渐】 艮下巽上","frontmatter":{"title":"53、【渐】 艮下巽上","description":"周易阐真 - 53、【渐】 艮下巽上"},"headers":[],"relativePath":"zh/classics/chanzhen/054.md","filePath":"zh/classics/chanzhen/054.md"}'),s={name:"zh/classics/chanzhen/054.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：渐之进也，女归吉也。进得位，往有功也。进以正，可以正邦也。其位刚得中也。止而巽，动不穷也。</p></blockquote><h1 id="_53、【渐】-艮下巽上" tabindex="-1">53、【渐】 艮下巽上 <a class="header-anchor" href="#_53、【渐】-艮下巽上" aria-label="Permalink to “53、【渐】 艮下巽上”">​</a></h1><p>初六：鸿渐于干。小子厉，有言，无咎。</p><p>六二：鸿渐于磐，饮食衎衎，吉。</p><p>九三：鸿渐于陆。夫征不复，妇孕不育，凶。利御寇。</p><p>六四：鸿渐于木，或得其桷，无咎。</p><p>九五：鸿渐于陵，妇三岁不孕。终莫之胜，吉。</p><p>上九：鸿渐于陆，其羽可用为仪，吉。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：山上有木，渐。君子以居贤德善俗。</p><p>渐者，徐缓也。上巽木，下艮山，是山上有木也。山上之木，形必高大，高大之木非一朝一夕而长成，此渐之象也。</p><p>君子有见于此，知德为人之根本，善为人之至宝。不能持守其德，则德不贤；不能变化气质，则善不大。以是效山之稳定，截然放下，居于贤德而不迁移；法木之生长，不急不缓，渐化俗气，而归至善焉。贤德者，至善之本性；俗者，旧染之俗气。俗不必拘于民俗，凡人七情六欲、贪嗔痴爱一切俗情，皆是也。居贤德，日用常行，无事不贤，无处不德，以贤德为居，身与贤德为一，不动不摇，止于至善矣。德善，则一切俗情旧染，亦渐次消化，变为真情，不隐不瞒，而俗归善矣。盖以真者既复，假者自化，真即在假之中，假不在真之外，贤德而俗必善，自然而然。居德善俗，俱用渐者，因人心用事已久，道心不彰，虽居德而不能遽然居之稳，善俗而不能遽然善之到。居德不稳，不谓德贤；善俗不到，不谓俗善。居德必至于无一德之不贤，方是居之稳；善俗必至于无一俗之不善，方是善之到。德贤俗善，先天足，后天化，只有善德，别无他物，返朴归醇，如山之稳定，如木之亭立，有为事毕，无为事彰，从此别立鼎器，再置钳锤，用天然真火，温养圣胎，可以入于神化不测之域矣。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>衎，音侃。桷，音角。</p><p>渐者，徐缓不速之义。卦德上巽入，下艮止，止于其所而徐入，故谓渐。此循序渐修之卦，承上震卦而来。震者，动而修省，不妄动也。不妄动，则戒慎恐惧，刚气在内，心坚志远，可以修金丹有为之道矣。有为之道，乃后天中返先天之道。返先天，所以使无者而复有，去者而仍还也。无者使有，去者仍还，非一朝一夕之功，其中火候细微，工程悠远，必须循序渐进，方能深造自得。</p><p>卦之刚止于内，柔巽于外，以刚用柔，借柔养刚，实以虚用，虚以实行，刚柔相当，虚实兼该，如二五阴阳相应，真阴真阳，自然匹配，非若假阴假阳，强求之合。是道也，如女归之道也。凡女归男，男先求女，用媒妁以通信，两家无嫌，然后女归男家，男贪女爱，生子生孙，夫妻偕老，此女归之吉，即男子之吉。若男不求女，女先求男，不用媒妁，私通苟合，急欲速成，不但女不吉，即男亦不吉。男女俱皆不吉，不过遂一时之乐，久必败事。故修道者，用渐修之功，不求速成，刚以柔用，如以男求女也；不急不缓，循序而进，愈久愈力，如用媒妁以礼通信也。功夫到日，由勉强而归自然，阴阳相合，刚柔混成，一粒灵丹，自虚无中凝结成象，如女归男，男女匹配，而自生育，是以渐修之道，如女归则吉也。</p><p>但渐道虽吉，尤利于渐之得正，若不得正，亦不得吉。彼世之炉火闺丹，着空执相之徒，有终身行之不休不歇者，何尝不云渐？但渐之不得其正，空空一世，到老无成，其吉安在?故必以正而渐，穷理尽性，以至于命，自有为而入无为，由勉强而抵自然，未有大道不成者也。</p><p>初六，在渐之至下，如鸿渐于干也。干为水涯下流之地，渐之于干，失其高飞之序。始不谨而终必凶，及至年满月尽，反怨丹经之谬，是小子危厉而有言矣。有言之厉，自取之耳，与人无咎。此柔而不正之渐也。</p><p>六二，止而得中，如鸿渐于磐矣。磐为平稳之石，磐亦非鸿止之处，渐之于磐，炼己待时，虚心即能实腹，是以饮食衎衎，乐在其中，其吉可知。此柔而得中之渐也。</p><p>九三，刚而不中，渐之太高，如鸿渐于陆矣。陆为平顶之大山，渐之于陆，失其自卑登高之序，急欲成功，阴阳不和，涉假伤真，如夫征不复，贪恋外妻，妇孕不育，私通奸夫，适以取凶而已。凶之者，以其刚道贵于止所而御寇，不贵于自用而为寇。此刚而失守之渐也。</p><p>六四，以柔居柔，如鸿渐于木，或得其桷矣。桷为屋角之平，木亦非鸿止之处。渐之于桷，或可暂时休歇。虚极静笃，以待阳复，自无当面错过之咎矣。此柔而守正之渐也。</p><p>九五，阳刚中正，如鸿渐于陵矣。陵为山之高而得中者。刚渐于中，燥气俱化，真阴真阳，性情和合，不复为假阴假阳所隔，如妇三岁不孕，终莫之胜也。真复假化，真阴真阳，两弦之气，结而为丹，不孕者亦孕，所谓“一粒金丹吞入腹，始知我命不由天”，其吉为何如乎?此刚柔混合之渐也。</p><p>上九，在渐之终，刚柔悉化，自卑登高，渐无可渐，圣胎完成，如鸿渐于陆，栖于平稳之处矣。渐于平稳，正当休歇罢工，修德修行，接引方来之时，是以其羽可用为仪吉。此全始全终之渐也。</p><p>六爻俱有渐道，惟初之太弱，三之太刚，非渐之吉道；其余四爻，皆循序渐进之功，或柔或刚，各随时而行，渐进之全体，大用毕露矣。</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
